<template><div class="shell"><header><strong>SCC CVE</strong><nav>漏洞监控　 <router-link to='/sources'>情报来源配置</router-link></nav><n-button quaternary @click="logout">退出</n-button></header><main><div class="head"><div><h2>漏洞监控</h2><n-text depth="3">WatchVuln 多源高价值漏洞情报</n-text></div><n-space><n-button type="error" :disabled="!checkedIds.length" :loading="deleting" @click="bulkDelete">批量删除（{{checkedIds.length}}）</n-button><n-button @click="openReviews">人工审核（{{pending.length}}）</n-button><n-button type="primary" :loading="refreshing" @click="refreshNow">立即采集</n-button></n-space></div><n-space style="margin:20px 0"><n-input v-model:value="q" clearable placeholder="搜索标题 / CVE" @keyup.enter="load"/><n-select v-model:value="severity" clearable placeholder="严重程度" style="width:130px" :options="options" @update:value="load"/><n-input v-model:value="source" clearable placeholder="来源" @keyup.enter="load"/><n-button @click="load">查询</n-button><n-text depth="3">共 {{total}} 条</n-text></n-space><n-data-table remote striped :row-key="row=>row.id" v-model:checked-row-keys="checkedIds" :columns="columns" :data="rows" :loading="loading" @update:expanded-row-keys="expandRows" :pagination="pagination" @update:page="changePage"/><n-modal v-model:show="show" preset="card" :title="selected?.title||'漏洞详情'" style="width:min(850px,95vw)"><n-descriptions v-if="selected" bordered :column="2"><n-descriptions-item label="CVE">{{selected.cve||'--'}}</n-descriptions-item><n-descriptions-item label="严重程度">{{selected.severity}}</n-descriptions-item><n-descriptions-item label="来源">{{selected.from}}</n-descriptions-item><n-descriptions-item label="披露时间">{{formatDate(selected.disclosure)}}</n-descriptions-item><n-descriptions-item label="采集时间">{{formatDate(selected.first_seen)}}</n-descriptions-item><n-descriptions-item label="描述" :span="2"><div style="white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;max-height:340px;overflow:auto">{{selected.description||'暂无描述'}}</div></n-descriptions-item><n-descriptions-item label="修复建议" :span="2">{{selected.solutions}}</n-descriptions-item></n-descriptions></n-modal><n-modal v-model:show="showReviews" preset="card" title="待人工确认的漏洞" style="width:min(1000px,95vw)"><n-data-table :columns="reviewColumns" :data="pending"/></n-modal></main></div></template>
<script setup>
import{h,ref,reactive,onMounted}from'vue'
import{useRouter}from'vue-router'
import{useMessage,NButton,NDataTable,NInput,NSelect,NSpace,NText,NTag,NModal,NDescriptions,NDescriptionsItem}from'naive-ui'
import{list,detail,refresh}from'../api'
import axios from 'axios'
const router=useRouter(),msg=useMessage(),rows=ref([]),total=ref(0),loading=ref(false),refreshing=ref(false),page=ref(1),q=ref(''),severity=ref(null),source=ref(''),show=ref(false),selected=ref(null)
const related=ref({}),expanded=ref([])
async function expandRows(keys){expanded.value=keys;for(const id of keys){if(related.value[id]!==undefined)continue;related.value={...related.value,[id]:null};try{const d=await axios.get('/api/v1/vulnerabilities/'+id+'/related',{headers:{Authorization:'Bearer '+(localStorage.getItem('token')||'')}});related.value={...related.value,[id]:d.data.data}}catch(e){related.value={...related.value,[id]:[]};msg.error('读取关联漏洞失败')}}}
const pending=ref([]),showReviews=ref(false),checkedIds=ref([]),deleting=ref(false)
async function bulkDelete(){if(!checkedIds.value.length)return;if(!confirm('确定永久删除选中的 '+checkedIds.value.length+' 条漏洞？关联审核记录也将删除。'))return;deleting.value=true;try{const response=await axios.post('/api/v1/vulnerabilities/bulk-delete',{ids:checkedIds.value},{headers:{Authorization:'Bearer '+(localStorage.getItem('token')||'')}});msg.success('已删除 '+response.data.data.deleted+' 条');checkedIds.value=[];await load();await loadReviews()}catch(e){msg.error(e.response?.data?.detail||e.message)}finally{deleting.value=false}}
const reviewHttp=axios.create({baseURL:'/api/v1/reviews'})
reviewHttp.interceptors.request.use(c=>{c.headers.Authorization='Bearer '+(localStorage.getItem('token')||'');return c})
async function loadReviews(){try{pending.value=(await reviewHttp.get('')).data.data}catch(e){msg.error(e.message)}}
async function openReviews(){await loadReviews();showReviews.value=true}
async function reviewAction(row,action){if(action==='approve'&&!confirm('确认推送该漏洞？'))return;try{await reviewHttp.post('/'+row.id+'/'+action);msg.success(action==='approve'?'已确认并推送':'已忽略');await loadReviews();await load()}catch(e){msg.error(e.response?.data?.detail||e.message)}}
const reviewColumns=[{title:'漏洞标题',key:'title',minWidth:280},{title:'命中关键词',key:'matched_keyword',width:130},{title:'采集时间',key:'first_seen',width:190,render:r=>formatDate(r.first_seen)},{title:'操作',key:'actions',width:180,render:r=>h(NSpace,{},()=>[h(NButton,{size:'small',type:'primary',onClick:()=>reviewAction(r,'approve')},()=> '确认推送'),h(NButton,{size:'small',onClick:()=>reviewAction(r,'reject')},()=> '忽略')])}]
const options=['严重','高危','中危','低危'].map(v=>({label:v,value:v}))
const pagination=reactive({page:1,pageSize:20,itemCount:0})
function formatDate(value){if(!value)return '--';let d=new Date(value);if(Number.isNaN(d.getTime()))return value;return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(d)}
const columns=[{type:'expand',expandable:r=>(r.group_count||1)>1,renderExpand:r=>related.value[r.id]===null?h('span','正在加载...'):h('div',{style:{padding:'10px 12px'}},[h('div',{style:{marginBottom:'8px',color:'#666'}},'相同 CVE 的其他 '+(related.value[r.id]?.length||0)+' 条情报（按首次采集时间排序）'),h(NDataTable,{size:'small',bordered:true,columns:[{title:'标题',key:'title',minWidth:250,render:x=>h(NButton,{text:true,type:'primary',onClick:()=>open(x.id)},()=>x.title)},{title:'等级',key:'severity',width:90},{title:'来源',key:'from',width:140},{title:'采集时间',key:'first_seen',width:190,render:x=>formatDate(x.first_seen)}],data:related.value[r.id]||[],rowKey:x=>x.id})])},{type:'selection',multiple:true},{title:'等级',key:'severity',width:90,render:r=>h(NTag,{type:r.severity==='严重'?'error':'warning'},()=>r.severity||'未知')},{title:'漏洞标题',key:'title',minWidth:300,render:r=>h(NButton,{text:true,type:'primary',onClick:()=>open(r.id)},()=>h('span',{style:{whiteSpace:'normal',overflowWrap:'anywhere',textAlign:'left',lineHeight:'1.5',display:'inline-block'}},r.title))},{title:'CVE',key:'cve',width:160},{title:'来源',key:'from',width:150,ellipsis:{tooltip:true}},{title:'披露时间',key:'disclosure',width:185,render:r=>formatDate(r.disclosure)},{title:'采集时间',key:'first_seen',width:185,render:r=>formatDate(r.first_seen)}]
async function load(){loading.value=true;try{const r=await list({page:page.value,size:20,grouped:true,q:q.value,severity:severity.value||'',source:source.value});rows.value=r.data.list;related.value={};total.value=r.data.total;pagination.itemCount=total.value}catch(e){msg.error(e.message)}finally{loading.value=false}}
async function open(id){try{selected.value=(await detail(id)).data;show.value=true}catch(e){msg.error(e.message)}}
async function refreshNow(){refreshing.value=true;try{await refresh();await load();msg.success('采集完成')}catch(e){msg.error(e.response?.data?.detail||e.message)}finally{refreshing.value=false}}
function changePage(p){page.value=p;pagination.page=p;load()}
function logout(){localStorage.removeItem('token');router.push('/login')}
onMounted(()=>{load();loadReviews()})
</script>
<style scoped>.shell{min-height:100vh;background:#f5f7fa;color:#243447}header{height:64px;background:#fff;display:flex;align-items:center;gap:36px;padding:0 32px;border-bottom:1px solid #eee}header strong{color:#2080f0;font-size:20px}header nav{flex:1}main{max-width:1500px;margin:32px auto;background:#fff;padding:24px;border-radius:10px;overflow-x:auto}.head{display:flex;justify-content:space-between;align-items:center}.head h2{margin:0}</style>